export function best1RMByDay(sets) {
  if (!Array.isArray(sets)) return [];
  const map = new Map();
  for (const set of sets) {
    if (set && set.done === true) {
      const key = dayKey(set.at);
      const epley = epley1RM(set.weight, set.reps);
      map.set(key, Math.max(map.get(key) || 0, epley));
    }
  }
  return Array.from(map.entries())
    .map(([key, value]) => ({ key, value }))
    .sort((a, b) => a.key.localeCompare(b.key));
}

export function sessionsPerWeek(sessions) {
  if (!Array.isArray(sessions)) return [];
  const map = new Map();
  for (const session of sessions) {
    if (!session) continue;
    const key = isoWeekKey(session.startedAt);
    map.set(key, (map.get(key) || 0) + 1);
  }
  return Array.from(map.entries())
    .map(([key, value]) => ({ key, value }))
    .sort((a, b) => a.key.localeCompare(b.key));
}

export function movingAverage(series, window) {
  if (!Array.isArray(series)) return [];
  if (!Number.isFinite(window) || window <= 1) {
    return series.map(({ key, value }) => ({ key, value }));
  }
  const result = [];
  for (let i = 0; i < series.length; i++) {
    let sum = series[i].value;
    let count = 1;
    for (let j = 1; j < window && i - j >= 0; j++) {
      sum += series[i - j].value;
      count++;
    }
    const average = Math.round((sum / count) * 100) / 100;
    result.push({ key: series[i].key, value: average });
  }
  return result;
}

// --- added by Claude for non-kg units (Stufe levels, timed holds) ---

/** Highest native load per day — best Stufe reached, or longest hold. */
export function maxLoadByDay(sets) {
  if (!Array.isArray(sets)) return [];
  const map = new Map();
  for (const set of sets) {
    if (!set || set.done !== true) continue;
    const w = Number(set.weight);
    if (!Number.isFinite(w) || w <= 0) continue;
    const key = dayKey(set.at);
    map.set(key, Math.max(map.get(key) || 0, w));
  }
  return Array.from(map.entries())
    .map(([key, value]) => ({ key, value }))
    .sort((a, b) => a.key.localeCompare(b.key));
}

/** Sum of native load per day — total seconds held across a session's planks. */
export function loadSumByDay(sets) {
  if (!Array.isArray(sets)) return [];
  const map = new Map();
  for (const set of sets) {
    if (!set || set.done !== true) continue;
    const w = Number(set.weight);
    if (!Number.isFinite(w) || w <= 0) continue;
    const key = dayKey(set.at);
    map.set(key, (map.get(key) || 0) + w);
  }
  return Array.from(map.entries())
    .map(([key, value]) => ({ key, value: Math.round(value * 100) / 100 }))
    .sort((a, b) => a.key.localeCompare(b.key));
}

