// --- per-exercise progression, bucketed by session / week / month ---
// The aggregation was generated by qwen2.5-coder:14b; Claude fixed two bugs in it (maxLoad
// called .filter() on the number Math.max returns, and each bucket kept the FIRST timestamp
// rather than the smallest, which mis-ordered weeks) and adapted it to v6's units, where a
// bodyweight set has no load at all and `counts()` decides what is countable.

export function monthKey(ts) {
  const date = new Date(ts);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  return `${year}-${month}`;
}

function bucketOf(set, bucket, sessionById) {
  let key, at;
  if (bucket === 'week') {
    key = isoWeekKey(set.at);
    at = set.at;
  } else if (bucket === 'month') {
    key = monthKey(set.at);
    at = set.at;
  } else {
    key = String(set.sessionId);
    const session = sessionById.get(set.sessionId);
    at = session && Number.isFinite(session.startedAt) ? session.startedAt : set.at;
  }
  return { key, at };
}

function labelFor(key, bucket, at) {
  if (bucket === 'week') return `KW ${key.slice(-2)}`;
  if (bucket === 'month') return new Date(at).toLocaleDateString(undefined, { month: 'short', year: 'numeric' });
  return new Date(at).toLocaleDateString(undefined, { day: '2-digit', month: 'short' });
}

export function progressSeries(sets, opts) {
  if (!Array.isArray(sets)) return [];
  const o = opts || {};
  const sessionById = Array.isArray(o.sessions)
    ? new Map(o.sessions.filter(Boolean).map((s) => [s.id, s]))
    : new Map();

  const buckets = new Map();
  for (const set of sets) {
    if (!set || set.done !== true) continue;
    const { key, at } = bucketOf(set, o.bucket, sessionById);
    if (!buckets.has(key)) buckets.set(key, { key, at, rows: [] });
    const b = buckets.get(key);
    if (Number.isFinite(at) && at < b.at) b.at = at;   // earliest moment wins, so weeks sort right
    b.rows.push(set);
  }

  const series = [];
  for (const { key, at, rows } of buckets.values()) {
    let value = 0;
    switch (o.metric) {
      case 'maxLoad':
        for (const s of rows) {
          const w = Number(s.weight);
          if (Number.isFinite(w) && w > 0 && w > value) value = w;
        }
        break;
      case 'best1rm':
        for (const s of rows) {
          if (!counts(s) || s.loadless === true) continue;
          const e = epley1RM(Number(s.weight), Number(s.reps));
          if (e > value) value = e;
        }
        break;
      case 'bestReps':
        for (const s of rows) {
          if (!counts(s)) continue;
          const r = Number(s.reps);
          if (r > value) value = r;
        }
        break;
      case 'reps':
        for (const s of rows) {
          if (!counts(s)) continue;
          const r = Number(s.reps);
          if (Number.isFinite(r) && r > 0) value += r;
        }
        break;
      case 'sets':
        for (const s of rows) if (counts(s)) value++;
        break;
      case 'nativeSum':
        for (const s of rows) {
          const w = Number(s.weight);
          if (Number.isFinite(w) && w > 0) value += w;
        }
        break;
      default:
        for (const s of rows) value += setVolume(s);
    }
    // A bucket worth 0 holds nothing countable for this metric — a session that was started
    // and never filled in, or sets ticked off with no numbers. Plotting it as a zero makes an
    // abandoned workout look like a total collapse, so it is left out entirely.
    if (value > 0) {
      series.push({ key, label: labelFor(key, o.bucket, at), value: Math.round(value * 100) / 100, at });
    }
  }

  return series.sort((a, b) => a.at - b.at);
}

export function withDeltas(series) {
  if (!Array.isArray(series)) return [];
  return series.map((entry, index) => {
    const prev = index > 0 ? series[index - 1] : null;
    const delta = prev ? Math.round((entry.value - prev.value) * 100) / 100 : null;
    const pct = prev && prev.value !== 0 ? Math.round((delta / prev.value) * 10000) / 100 : null;
    return { ...entry, delta, pct };
  });
}
